True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    divider_rows = {r for r in range(h) if all(v == 0 for v in out[r])}
    divider_cols = {c for c in range(w) if all(out[r][c] == 0 for r in range(h))}
    for r in divider_rows:
        for c in range(w):
            out[r][c] = 2
    for c in divider_cols:
        for r in range(h):
            out[r][c] = 2
    return out
